CREATE FUNCTION [dbo].[fnGetResultsForTag]
(  
    @elapsedTimeTag NVARCHAR(50)
)
RETURNS TABLE 
AS
RETURN 
(
    SELECT tag, time, value
    FROM PIpiarchivepicount
    WHERE tag = @elapsedTimeTag
        AND filterexpr = QUOTENAME(@elapsedTimeTag, '''') + ' > NEXTVAL(' + QUOTENAME(@elapsedTimeTag, '''') + ', ''*'')'
        AND time BETWEEN (SELECT result FROM PIpifunctiondate WHERE arg1='t-20h') AND (SELECT result FROM PIpifunctiondate WHERE arg1='*')
        AND timestep = (SELECT result FROM PIpifunctiontime WHERE arg1='12h')
        AND calcbasis = 'EventWeighted'
);
GO

