CREATE VIEW v_entity_curr_version (
    entity_id,
    version_id
) AS
SELECT ev.entity_id,
       MAX(ev.version_id) KEEP(dense_rank LAST ORDER BY ev.created_timestamp) AS version_id
  FROM entity_version ev
 GROUP BY ev.entity_id;

